        svgHtml += '<text x="130" y="176" text-anchor="middle" fill="' + (isThinning ? '#f59e0b' : '#10b981') + '" font-size="10.5" font-weight="bold">' + (isThinning ? '✓ RCTC Active: Prevents Rubbing' : '✓ Standard Chip Load Engaged') + '</text>';
